#!/usr/bin/env bash
# Shell completion for alexa-cli. The script is generated by `alexa-cli completion <shell>` from the same command
# declarations as the parser, written to ~/.config/alexa-cli, and sourced from your shell rc.
# Idempotent: re-run any time (after an update, to pick up new commands) — the rc line is only added once.
#
# Usage: install-completion.sh [bash|zsh|fish]        (default: $SHELL)
#        install-completion.sh --uninstall [bash|zsh|fish]
set -euo pipefail

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
UNINSTALL=0
if [ "${1:-}" = "--uninstall" ]; then UNINSTALL=1; shift; fi
shell="${1:-$(basename "${SHELL:-bash}")}"
conf_dir="${ALEXA_CLI_CONFIG_DIR:-$HOME/.config/alexa-cli}"

case "$shell" in
    bash) script="$conf_dir/completion.bash"; rc="$HOME/.bashrc" ;;
    zsh) script="$conf_dir/completion.zsh"; rc="$HOME/.zshrc" ;;
    fish) script="$HOME/.config/fish/completions/alexa-cli.fish"; rc="" ;;
    *) echo "error: unsupported shell '$shell' (bash, zsh or fish)" >&2; exit 1 ;;
esac
line="[ -f $script ] && . $script"

if [ "$UNINSTALL" = 1 ]; then
    rm -f "$script"
    if [ -n "$rc" ] && [ -f "$rc" ]; then
        grep -vF -e "$line" -e "# alexa-cli shell completion" "$rc" > "$rc.alexa-cli.tmp" && mv "$rc.alexa-cli.tmp" "$rc"
    fi
    echo "Removed $script"
    exit 0
fi

mkdir -p "$(dirname "$script")"
node "$REPO/bin/alexa-cli.js" completion "$shell" > "$script"
echo "Wrote $script"
if [ -z "$rc" ]; then
    echo "fish loads it by itself; open a new shell."
elif grep -Fqs "$script" "$rc"; then
    echo "Already sourced from $rc."
else
    printf '\n# alexa-cli shell completion\n%s\n' "$line" >> "$rc"
    echo "Added to $rc — open a new shell or: source $rc"
fi
